// Profile facts from the user's Drive: school Gantt, general profile, team and routines.
const selectedSchool={name:'יסודי אלמג׳ד ב׳ אל־מכסור',code:'218230',level:'יסודי',students:'410',classes:'19'};
const team=[['נדים ג׳בור','מנהל מרכז פסג״ה','הובלה מערכתית, חיבור לשותפים והסרת חסמים','נג'],['חסן ח׳טיב','מוביל פיילוט 67/67','תכלול הפיילוט, תוכנית העבודה ואבני הדרך','חח'],['רודיינה נסאר','מלוות בית הספר','בניית שותפות, ליווי יישום ורפלקציה בשטח','רנ'],['אמל אליאס','הערכה ומדידה','הגדרת מדדים, איסוף ראיות וניתוח נתונים','אא'],['פלורידה חורי','תפעול, תיעוד וארגון','ריכוז מסמכים, סיכומי החלטות ומעקב משימות','פח']];
const schoolSource='https://docs.google.com/spreadsheets/d/1h42RvxgiaXH0DB2s82-xEzpHl-KW-UFlYseOvlv2_AI/edit';
const centerSource='https://drive.google.com/file/d/1x-UFig5DTbeMnh7DHVYBl0bek6ar01aE/view';
const profileSource='https://docs.google.com/document/d/1iLCsXu-cQrkkXaSA88GOn6l2U6xx3mJqNOIY8L9k9h8/edit';
function externalLink(url,text){return `<a target="_blank" rel="noopener" href="${url}">${text} ↗</a>`}
stages[0].tasks[0]='בחרנו בית ספר לפיילוט — יסודי אלמג׳ד ב׳ אל־מכסור';
function applySchoolProfile(){if(data.pisgaProfileVersion)return;let target=data.schools.find(s=>String(s.code||'').trim()==='218230');if(!target)target=data.schools.find(s=>!Object.values(s).some(Boolean));if(!target){target={};data.schools.push(target)}for(const [key,value] of Object.entries(selectedSchool))if(!target[key])target[key]=value;data.checks[0][0]=true;data.pisgaProfileVersion=1;save()}
applySchoolProfile();
document.querySelector('nav').insertAdjacentHTML('beforeend','<button data-view="pisga">פסג״ה שפרעם</button>');
document.querySelector('.brand small').textContent='מרכז פסג״ה אזורי שפרעם';
document.querySelector('.profile').innerHTML='<a class="pisgaBrand" href="#" data-view="pisga" aria-label="פסג״ה שפרעם — פיילוט 67"><b>67<span>↗</span></b><div>פסג״ה שפרעם<small>פיילוט 67/67 · לומדים ומשפיעים</small></div></a>';
document.querySelector('.intro .eyebrow').textContent='מרכז פסג״ה אזורי שפרעם · פיילוט 67/67';
document.querySelector('.intro h1').textContent='שותפות שמובילה שינוי.';
document.querySelector('.intro p:not(.eyebrow)').textContent='מסע הלמידה המשותף של פסג״ה שפרעם ובית הספר אלמג׳ד ב׳ אל־מכסור.';
const dashboard=document.createElement('section');dashboard.className='partnership';dashboard.setAttribute('aria-label','המרכז המלווה ובית הספר שנבחר');dashboard.innerHTML=`<div class="centerSummary"><span class="visualIcon">✧</span><div><span class="cardEyebrow">המרכז המלווה</span><h2>מרכז פסג״ה אזורי שפרעם</h2><p>הובלה · פיתוח מקצועי · ליווי מבוסס ראיות</p><button data-view="pisga">הכירו את הצוות והשותפות ←</button></div></div><div class="chosenSummary"><div class="chosenTop"><span class="cardEyebrow">בית הספר שנבחר לפיילוט</span><span class="chosenBadge">✓ הבחירה הושלמה</span></div><h2>${selectedSchool.name}</h2><div class="schoolNumbers"><div><b>218230</b><span>סמל מוסד</span></div><div><b>410</b><span>תלמידים</span></div><div><b>19</b><span>כיתות</span></div><div><b>יסודי</b><span>שלב חינוך</span></div></div><div class="profileLinks">${externalLink(schoolSource,'תיעוד בחירת בית הספר')}${externalLink(profileSource,'מקור נתוני הפרופיל')}</div></div>`;
document.querySelector('.overview').before(dashboard);
const baseProfileRender=render;
function pisgaView(){return `<div class="pisgaHero"><span class="cardEyebrow">הבית של הלמידה המקצועית</span><h2>מרכז פסג״ה אזורי שפרעם</h2><p>מובילים יחד תהליך של אבחון, תכנון, ליווי, הערכה והפקת תובנות בפיילוט 67/67.</p><span class="heroMark" aria-hidden="true">↗</span></div><div class="profileSectionHeading"><h3>הצוות המוביל</h3><span>אחריות ברורה · עבודה משותפת</span></div><div class="teamGrid">${team.map((p,i)=>`<article class="person person${i}"><span class="avatar" aria-hidden="true">${p[3]}</span><small>${p[1]}</small><h4>${p[0]}</h4><p>${p[2]}</p></article>`).join('')}<article class="person person5"><span class="avatar" aria-hidden="true">◇</span><small>הנחיה מקצועית</small><h4>בהתאם לצורך הבית־ספרי</h4><p>התאמת הלמידה, חיבור לפרקטיקה ומשימות יישום. לא צוין שם במסמך.</p></article></div><p class="profileSource">${externalLink(centerSource,'מקור: הרכב הצוות המוביל וחלוקת תפקידים')} · הנתונים מוצגים כפי שתועדו בקבצים.</p><div class="profileSectionHeading"><h3>השותפות בשטח</h3></div><div class="partnerFlow"><div><b>פסג״ה שפרעם</b><span>ליווי, למידה, הערכה ותיעוד</span></div><span class="flowArrow" aria-hidden="true">⇄</span><div><b>יסודי אלמג׳ד ב׳ אל־מכסור</b><span>יישום בכיתות ולמידה מהשטח</span></div></div><div class="routineCard"><span class="visualIcon">◷</span><div><small>שגרת המפגשים שנקבעה</small><h3>יום שלישי · 09:00–10:30</h3><p>אחת לשבועיים או לחודש, בהתאם לצורך ולהתקדמות התהליך.</p></div></div><div class="routineSteps">${[['10','פתיחה ותמונת מצב'],['20','בחינת היישום'],['20','נתונים וראיות'],['20','חסמים והתאמות'],['15','החלטות להמשך'],['5','סיכום ותיעוד']].map(r=>`<div><b>${r[0]}<small>דקות</small></b><span>${r[1]}</span></div>`).join('')}</div><p class="profileSource">${externalLink('https://drive.google.com/file/d/1N4eXXD3qpY80sz4Xn1I7MAGqfkX7oRKZ/view','מקור: שגרות עבודה 67')} · סך הכול 90 דקות.</p><div class="pisgaPrinciple"><b>מהשטח להחלטות — ומההחלטות לשטח</b><p>שותפות קבועה, נתונים וראיות, רפלקציה וחלוקת אחריות לאורך התהליך.</p></div>`}
render=function(){baseProfileRender();if(view==='pisga')$('content').innerHTML=pisgaView();if(view==='journey'&&data.stage===0)$('content').insertAdjacentHTML('beforeend',`<div class="selectionEvidence"><b>✓ בחירת בית הספר מתועדת בלוח הגאנט</b><p>יסודי ב׳ אלמכסור — נבחר לפיילוט באחריות פסג״ה. הבחירה עודכנה ברשימת המשימות.</p>${externalLink(schoolSource,'צפייה במקור')}</div>`);if(view==='schools')$('content').insertAdjacentHTML('afterbegin',`<div class="selectionEvidence"><b>בית הספר שנבחר: ${selectedSchool.name}</b><p>סמל מוסד 218230 · 410 תלמידים · 19 כיתות. פרטים שהוזנו ידנית נשמרים.</p>${externalLink(profileSource,'פרופיל המקור')}</div>`)};
const originalImportHandler=$('import').onchange;$('import').onchange=async e=>{await originalImportHandler(e);applySchoolProfile();render()};
const asideBlue=document.querySelector('.asideCard.blue');asideBlue.classList.add('partnershipImageCard');asideBlue.innerHTML='<div class="partnershipImage"><img src="assets/partnership-learning.png" alt="איור של בתי ספר מחוברים, צמיחה ומסלול למידה מבוסס נתונים" width="391" height="197"></div><div class="partnershipImageText"><p class="eyebrow">פסג״ה שפרעם × אלמג׳ד ב׳</p><h3>שותפות מקצועית.<br>השפעה בכיתה.</h3><p>מחברים בין צורכי בית הספר, הלמידה המקצועית של המורים והראיות מהשטח.</p></div>';
render();


